const expData={fid:[5.604571,.701002,null,167.6,170.582,332.847],labels:['Exp 1','Exp 2','Exp 3','Exp 4','Exp 5','Exp 6']};
function barChart(id,values,labels){const el=document.getElementById(id);if(!el)return;const max=Math.max(...values.filter(v=>v!==null));const w=520,h=190,p=24,bw=52,g=42;let s=`<svg viewBox="0 0 ${w} ${h}" role="img"><line x1="${p}" y1="${h-p}" x2="${w-p}" y2="${h-p}" stroke="#d8d7d1"/>`;values.forEach((v,i)=>{const x=p+18+i*(bw+g);if(v===null){s+=`<rect x="${x}" y="${h-p-5}" width="${bw}" height="5" rx="2" fill="#d8d7d1"/><text x="${x+bw/2}" y="${h-p-17}" text-anchor="middle" font-size="11" fill="#697278">pending</text>`}else{const bh=Math.max(8,(h-2*p)*v/max);s+=`<rect x="${x}" y="${h-p-bh}" width="${bw}" height="${bh}" rx="6" fill="${i===1?'#2f6d8f':'#e35d2f'}"/><text x="${x+bw/2}" y="${h-p-bh-9}" text-anchor="middle" font-size="11" fill="#171b1e">${v}</text>`}s+=`<text x="${x+bw/2}" y="${h-5}" text-anchor="middle" font-size="11" fill="#697278">${labels[i]}</text>`});el.innerHTML=s+'</svg>'}
async function lineChart(id){const el=document.getElementById(id);if(!el)return;let pts=[];try{const raw=await fetch('assets/data/exp4_training_loss.csv').then(r=>r.text());pts=raw.trim().split(/\r?\n/).slice(1).map(r=>Number(r.split(',')[1])).filter(Number.isFinite)}catch(e){}if(!pts.length){el.innerHTML='<p class="chart-footnote">Training-loss CSV unavailable.</p>';return}const stride=Math.max(1,Math.floor(pts.length/24));pts=pts.filter((_,i)=>i%stride===0||i===pts.length-1);const max=Math.max(...pts),min=Math.min(...pts),w=520,h=190,p=24;const xy=pts.map((v,i)=>[p+i*(w-2*p)/(pts.length-1||1),h-p-((v-min)/(max-min||1))*(h-2*p)]);const d=xy.map((a,i)=>(i?'L':'M')+a[0].toFixed(1)+' '+a[1].toFixed(1)).join(' ');el.innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img"><line x1="${p}" y1="${h-p}" x2="${w-p}" y2="${h-p}" stroke="#d8d7d1"/><path d="${d}" fill="none" stroke="#2f6d8f" stroke-width="3" stroke-linecap="round"/><circle cx="${xy.at(-1)[0]}" cy="${xy.at(-1)[1]}" r="5" fill="#e35d2f"/><text x="${p}" y="18" font-size="11" fill="#697278">${pts[0].toFixed(4)}</text><text x="${w-p}" y="18" text-anchor="end" font-size="11" fill="#697278">${pts.at(-1).toFixed(4)}</text></svg>`}
barChart('fid-chart',expData.fid,expData.labels);lineChart('loss-chart');
const lightbox=document.getElementById('lightbox');const lightboxImg=lightbox.querySelector('img');document.querySelectorAll('.gallery-grid img').forEach(img=>img.addEventListener('click',()=>{lightboxImg.src=img.src;lightboxImg.alt=img.alt;lightbox.classList.add('open')}));function closeBox(){lightbox.classList.remove('open');lightboxImg.src=''}lightbox.querySelector('.lightbox-close').addEventListener('click',closeBox);lightbox.addEventListener('click',e=>{if(e.target===lightbox)closeBox()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeBox()});
document.querySelectorAll('button.exp-open').forEach(btn=>btn.addEventListener('click',()=>{const card=btn.closest('.experiment-card');const n=card.dataset.exp;const target=Number(n)>=5?'#archive':'#evidence';document.querySelector(target).scrollIntoView({behavior:'smooth'})}));
